// n8n Code node — place between the form-parsing node and the /create-student HTTP node.
// Input: expects the form's "Your Subscription period" answer on $json.subscriptionPeriod
// (rename to match your actual field key) and, if "Other" was picked, the free-text
// value on $json.subscriptionPeriodOther.
// Output: adds $json.planmonths set to the exact `name` stored in Firestore's
// subscriptionPlans collection, so /create-student's `name == planmonths` match succeeds.

const FORM_TO_PLAN_NAME = {
  '16 days': '16 DAYS PLAN',
  '1 month': '1 MONTH PLAN',
  '2 month': '2 MONTH PLAN',
  '3 month': '3 MONTH PLAN',
  '3 months': '3 MONTH PLAN',
  '1 day': '1 day',
  '365 days': '365 Days Plan',
};

const raw = $input.first().json['Your Subscription period'];
const answer = raw === 'Other' ? $input.first().json['Your Subscription period'] : raw;
const planName = FORM_TO_PLAN_NAME[String(answer).trim().toLowerCase()];

if (!planName) {
  throw new Error(`No matching subscription plan for form answer: "${answer}"`);
}

return { ...$input, planmonths: planName };

